import {obligationControl} from './control-model.js?v=23';
import {financialHierarchyHTML} from './financial-hierarchy-ui.js?v=34';
import {obligationCategory} from './financial-hierarchy.js?v=30';
import {planningBook,planningSummary,planningRemaining,planningPaid} from './planning-book-model.js?v=31';
import {planningCoverageHTML,planningReferenceHTML,planningAgendaHTML} from './planning-book-ui.js?v=31';
import {statementOrder} from './statement-model.js?v=17';
import {MONTHS,figures,total} from './data.js?v=17';
import {monthDays} from './workbook-model.js?v=17';
import {createPeriodSheet} from './period-ui.js?v=34';

export function createCashbook(a) {
  const {esc,money,date,fullDate,icon,btn,pill,link,panel,empty,stat}=a;
  let selected=a.state.dataset?.defaultDate||'2026-07-18',mode='daily',includeInitial=true,ledgerGrouped=true;
  const periodSheet=createPeriodSheet(a,{get selected(){return selected},pick,controls});
  const name=()=>MONTHS[Number(a.month.slice(5))-1]+' de '+a.month.slice(0,4);
  const book=()=>planningBook(a.state,a.company,{start:a.month+'-01',end:monthDays(a.month).at(-1)},'daily',a.account,a.NOW);
  const getDay=()=>{if(selected.slice(0,7)!==a.month)selected=a.month+'-01';return book().find(d=>d.date===selected)||book()[0]};
  const daysOptions=()=>monthDays(a.month).map(d=>`<option value="${d}" ${d===selected?'selected':''}>${fullDate(d)}</option>`).join('');
  const weekday=d=>new Intl.DateTimeFormat('pt-BR',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).replace('.','');
  function pick(value) {selected=value;a.setMonth(value.slice(0,7));}
  function controls(suffix='page'){return `<div class="day-picker"><button data-book-shift="-1" aria-label="Dia anterior">${icon('back')}</button><label class="sr-only" for="book-date-${suffix}">Dia selecionado</label><input id="book-date-${suffix}" type="date" value="${selected}" data-book-day><button data-book-shift="1" aria-label="Próximo dia">${icon('chevron')}</button></div>`}
  function homeDay(){const d=getDay();return `<section class="home-daily"><div><span class="eyebrow">Sua mesa de trabalho</span><h2>O dia em detalhe</h2><p>${weekday(d.date)} · ${fullDate(d.date)} · ${d.transactions.length} movimento(s), ${d.obligations.length} vencimento(s), ${d.tasks.filter(t=>!t.done).length} tarefa(s) abertas</p></div><div class="home-daily-actions">${controls()}${btn('Abrir dia',`data-open="day" data-id="${d.date}"`,'','chevron')}${btn('Ver planilha diária','data-book-go="daily"','','flow')}</div></section>`}
  const obligationStatus=o=>{const c=obligationControl(a.state,o,a.NOW);return {label:c?.label||'Cancelada',tone:({overdue:'red',deviation:'red',verify:'amber',due:'amber',planned:'blue',resolved:'green'})[c?.group]||'blue'};};
  const amount=value=>value==null?'—':money(value);
  function monthFigures(id){
    const range={start:id+'-01',end:monthDays(id).at(-1)},p=planningBook(a.state,a.company,range,'monthly',a.account,a.NOW)[0];
    return {...p,range,balance:p.closing,toReceive:p.pendingIn,toPay:p.pendingOut};
  }
  function classificationOption(){return `<label class="fh-option"><input type="checkbox" data-book-initial ${includeInitial?'checked':''}> Incluir classificações iniciais (a revisar)</label>`;}
  function annualSummary(){return planningSummary(planningBook(a.state,a.company,{start:a.month.slice(0,4)+'-01-01',end:a.month.slice(0,4)+'-12-31'},'yearly',a.account,a.NOW));}
  function financialTotals(s){return `<div class="book-totals planning-totals"><div><span>Saldo realizado · abertura</span><strong>${amount(s.opening)}</strong></div><div class="income"><span>Entradas registradas</span><strong>${money(s.incoming)}</strong></div><div class="expense"><span>Saídas registradas</span><strong>${money(s.outgoing)}</strong></div><div class="closing"><span>Saldo realizado · fechamento</span><strong>${amount(s.closing)}</strong></div><div class="reference"><span>Referência · posições por conta</span><strong>${amount(s.reference)}</strong></div><div class="projection"><span>Projeção · com obrigações</span><strong>${amount(s.projected)}</strong></div></div>`;}
  function annual(){return panel('Resumo anual','Todos os meses podem ser abertos, inclusive futuros e sem extrato.',`<div class="table-wrap"><table class="annual"><thead><tr><th>Mês / cobertura</th><th>Entradas registradas</th><th>Saídas registradas</th><th>A receber</th><th>A pagar</th><th>Saldo realizado</th><th>Referência</th><th>Projeção</th></tr></thead><tbody>${MONTHS.map((m,i)=>{const id=`${a.month.slice(0,4)}-${String(i+1).padStart(2,'0')}`,f=monthFigures(id);return `<tr><td><button class="textbtn" data-book-month="${id}">${m}</button><small>${f.complete?'Cobertura completa':f.coverage.some(c=>c.status==='full'||c.status==='partial')?'Extrato parcial':'Sem extrato'}</small></td><td class="money incoming">${money(f.incoming)}</td><td class="money outgoing">${money(f.outgoing)}</td><td class="money">${money(f.toReceive)}</td><td class="money">${money(f.toPay)}</td><td class="money">${amount(f.balance)}</td><td class="money">${amount(f.reference)}</td><td class="money">${amount(f.projected)}</td></tr>`}).join('')}</tbody></table></div>`);}
  function comparison(f){
    const directions=[['in','A receber'],['out','A pagar']];
    const body=directions.map(([kind,label])=>{
      const groups=new Map();
      for(const o of f.obs.filter(o=>o.kind===kind)){const category=obligationCategory(a.state,a.company,o);if(!groups.has(category.id))groups.set(category.id,{...category,items:[]});groups.get(category.id).items.push(o);}
      if(!groups.size)return '';
      return `<details class="fh-direction" open><summary>${label}</summary>${[...groups.values()].map(g=>`<details class="fh-category"><summary>${esc(g.label)} · ${g.items.length} obrigação(ões)</summary><div class="table-wrap"><table><thead><tr><th>Vencimento</th><th>Obrigação / origem</th><th>Previsto</th><th>Realizado</th><th>Em aberto</th><th>Situação</th></tr></thead><tbody>${g.items.sort((x,y)=>x.due.localeCompare(y.due)).map(o=>`<tr><td>${date(o.due)}</td><td><button class="textbtn" data-open="obligation" data-id="${esc(o.id)}">${esc(o.title)}</button><small>${esc(o.party)}</small></td><td class="money">${money(total(o))}</td><td class="money">${money(planningPaid(a.state,o))}</td><td class="money">${money(planningRemaining(a.state,o))}</td><td>${pill(obligationStatus(o).label,obligationStatus(o).tone)}</td></tr>`).join('')}<tr><th colspan="2">Subtotal</th><td class="money">${money(g.items.reduce((n,o)=>n+total(o),0))}</td><td class="money">${money(g.items.reduce((n,o)=>n+planningPaid(a.state,o),0))}</td><td class="money">${money(g.items.reduce((n,o)=>n+planningRemaining(a.state,o),0))}</td><td></td></tr></tbody></table></div></details>`).join('')}</details>`;
    }).join('');
    return panel('Previsto × realizado','A receber / A pagar · Classificação · Obrigações. A classificação da obrigação é própria; não é presumida a partir de um pagamento.',`<div class="financial-hierarchy"><p class="fh-note">Obrigações ainda sem classificação ficam em A classificar. Composições mistas e pagamentos parciais aguardam distribuição, sem rateio automático.</p>${body||empty('Sem obrigações no período','Crie uma obrigação a partir de um modelo.')}</div>`);
  }
  function flow(){
    getDay();
    const f=figures(a.state,a.company,a.month,a.account),view=mode==='daily'?periodSheet.summary():mode==='annual'?annualSummary():planningSummary(book());
    return a.titleBlock('Fluxo de caixa','A lógica da sua planilha, do período ao lançamento.',(mode==='daily'?'':`<input type="month" class="monthpick" aria-label="Mês de referência" data-month-select value="${a.month}">`)+btn('Adicionar','data-open="add"','primary','plus'),'Financeiro · livro caixa')+
      `${mode==='daily'?'':planningCoverageHTML(a,{start:view.start,end:view.end})}${financialTotals(view)}${planningReferenceHTML(a,view)}<div class="toolbar book-toolbar"><div class="segments">${[['daily','Planilha'],['ledger','Lançamentos'],['compare','Previsto × realizado'],['annual','Resumo anual']].map(([key,label])=>`<button data-book-view="${key}" class="${mode===key?'active':''}" aria-pressed="${mode===key}">${label}</button>`).join('')}</div>${mode!=='daily'?`<div class="filters"><select aria-label="Filtrar conta" data-account><option value="all">Todas as contas</option>${a.scope('accounts').map(x=>`<option value="${x.id}" ${a.account===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${mode==='daily'?btn('Exportar grade','data-book-export="1"','','download'):btn('Exportar lançamentos','data-action="export-flow"','','download')}</div>`:''}</div>`+
      (mode==='daily'?periodSheet.render():mode==='ledger'?panel(name(),'Entradas / Saídas · Classificação · Lançamentos.',classificationOption()+btn(ledgerGrouped?'Ver lista cronológica':'Agrupar por classificação','data-book-ledger-layout="1"')+(ledgerGrouped?financialHierarchyHTML(a,f.current,{includeInitial}):a.transactionTable([...f.current].sort(statementOrder),true))):mode==='compare'?comparison({...f,obs:view.obligations}):annual()+panel('Classificações do ano',a.month.slice(0,4)+' · mesmo filtro de contas e cobertura do resumo mensal.',classificationOption()+financialHierarchyHTML(a,annualSummary()?.transactions||[],{includeInitial})))+(mode==='daily'?'':planningAgendaHTML(a,view));
  }
  function dayDetail(id){pick(id);a.render();const d=getDay();return {heading:'Visualização diária',wide:true,body:`<div class="day-detail-head"><div><span class="eyebrow">${esc(a.get('companies',a.company).name)} · ${a.account==='all'?'Todas as contas':esc(a.get('accounts',a.account).name)}</span><h2>${fullDate(d.date)} <small>${weekday(d.date)}</small></h2></div>${controls('dialog')}</div>${planningCoverageHTML(a,{start:d.date,end:d.date})}${financialTotals(d)}${planningReferenceHTML(a,d)}<div class="day-detail-grid"><div><div class="drawer-section"><h3>Movimentos realizados <span class="count-badge">${d.transactions.length}</span></h3>${financialHierarchyHTML(a,d.transactions,{includeInitial})}</div><div class="drawer-section"><h3>Previsões a confirmar <span class="count-badge">${d.forecasts.length}</span></h3><p class="annotation">Sugestões separadas dos saldos e das obrigações.</p>${d.forecasts.map(f=>link(f.title,'forecast',f.id,`${money(f.amount*f.direction)} · ${f.label}`,'calendar')).join('')||'<p class="annotation">Nenhuma previsão disponível nesta data.</p>'}</div><div class="drawer-section"><h3>Obrigações com vencimento no dia <span class="count-badge">${d.obligations.length}</span></h3>${d.obligations.map(o=>link(o.title,'obligation',o.id,`${money(total(o))} · ${obligationStatus(o).label} · em aberto ${money(planningRemaining(a.state,o))}`,'calendar')).join('')||'<p class="annotation">Nenhum vencimento cadastrado para esta data.</p>'}</div></div><div><div class="drawer-section"><h3>Tarefas do dia <span class="count-badge">${d.tasks.length}</span></h3>${d.tasks.map(t=>link(t.title,'task',t.id,`${t.owner} · ${t.done?'Concluída':'A fazer'}`,'task')).join('')||'<p class="annotation">Nenhuma tarefa com prazo nesta data.</p>'}</div><div class="callout">${icon('info')}<span>Vencimento, realização financeira e tarefa têm datas próprias. Os valores bancários só mudam quando existe um movimento.</span></div>${btn('Adicionar neste contexto','data-open="add"','primary','plus')}</div></div>`}}
  function redrawDay(){a.render();if(a.current?.kind==='day'){a.current.id=selected;a.draw()}}
  function click(d){if(d.bookLedgerLayout){ledgerGrouped=!ledgerGrouped;a.render();return true;}if(periodSheet.click(d))return true;if(d.bookGo){mode=d.bookGo;if(mode==='daily')periodSheet.daily();a.navigate('flow');return true}if(d.bookView){mode=d.bookView;a.render();return true}if(d.bookMonth){a.setMonth(d.bookMonth);selected=d.bookMonth+'-01';mode='daily';periodSheet.daily('month');a.render();return true}if(d.bookShift){const dt=new Date(selected+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+Number(d.bookShift));pick(dt.toISOString().slice(0,10));redrawDay();return true}return false}
  function change(e){if(e.target.hasAttribute('data-book-initial')){includeInitial=e.target.checked;a.render();return true;}if(periodSheet.change(e))return true;if(e.target.hasAttribute('data-book-day')){if(e.target.value){pick(e.target.value);redrawDay()}return true}return false}
  return {flow,homeDay,click,change,openRange(range,account){mode='daily';a.setAccount(account);periodSheet.setRange(range)},selectDate(value){pick(value)},get selectedDate(){return getDay().date},dialog:(kind,id)=>kind==='day'?dayDetail(id):null};
}
